package main

import (
	"bufio"
	"fmt"
	"os"
	"strconv"
	"strings"

	"github.com/shopspring/decimal"
)

type PartRec struct {
	LbPart   string
	LbRegion string
	LbSerial int64
}

var WsEofFlag string = "N"
var WsLabel string = strings.Repeat(" ", 20)
var WsACount int64 = 0
var WsTotalA int64 = 0
var WsCount int64 = 0

var partRec PartRec
var partFileLines []string
var partFileIdx int

func isInputDone() bool {
	return WsEofFlag == "Y"
}

func formatNumeric(v int64, width int) string {
	s := strconv.FormatInt(v, 10)
	// Truncate high-order digits if overflow (keep low-order)
	if len(s) > width {
		// handle negative? not needed here
		if s[0] == '-' {
			// keep sign? COBOL would drop high-order digits; simplify
			s = s[len(s)-width:]
		} else {
			s = s[len(s)-width:]
		}
	}
	if len(s) < width {
		// zero pad on left; for negative, pad after minus
		if strings.HasPrefix(s, "-") {
			s = "-" + strings.Repeat("0", width-len(s)) + s[1:]
		} else {
			s = strings.Repeat("0", width-len(s)) + s
		}
	}
	return s
}

func trimAtSpace(s string) string {
	if idx := strings.IndexByte(s, ' '); idx >= 0 {
		return s[:idx]
	}
	return s
}

func mainPara() {
	// OPEN INPUT PART-FILE
	f, err := os.Open("input.dat")
	if err == nil {
		scanner := bufio.NewScanner(f)
		// Allow long lines
		buf := make([]byte, 0, 64*1024)
		scanner.Buffer(buf, 10*1024*1024)
		for scanner.Scan() {
			line := scanner.Text()
			// Remove trailing \r if present (LINE SEQUENTIAL)
			if len(line) > 0 && line[len(line)-1] == '\r' {
				line = line[:len(line)-1]
			}
			partFileLines = append(partFileLines, line)
		}
		f.Close()
	} else {
		// if file cannot be opened, treat as empty
		partFileLines = []string{}
	}
	partFileIdx = 0

	readPara()
	for !isInputDone() {
		processPara()
	}
	// CLOSE PART-FILE (already closed)
	summaryPara()
}

func readPara() {
	if partFileIdx >= len(partFileLines) {
		WsEofFlag = "Y"
		return
	}
	line := partFileLines[partFileIdx]
	partFileIdx++

	// Pad with spaces on right if shorter than record length (15)
	if len(line) < 15 {
		line = line + strings.Repeat(" ", 15-len(line))
	}
	if len(line) > 15 {
		line = line[:15]
	}
	partRec.LbPart = line[0:8]
	partRec.LbRegion = line[8:11]
	serialStr := line[11:15]
	serialStr = strings.TrimSpace(serialStr)
	if serialStr == "" {
		partRec.LbSerial = 0
	} else {
		// keep only digits? but assume digits
		n, err := strconv.ParseInt(strings.TrimSpace(serialStr), 10, 64)
		if err != nil {
			// if contains spaces, fallback to 0
			n = 0
			// try to parse digits ignoring spaces
			trimmed := strings.TrimSpace(serialStr)
			if trimmed != "" {
				if v, e2 := strconv.ParseInt(trimmed, 10, 64); e2 == nil {
					n = v
				}
			}
		}
		partRec.LbSerial = n
	}
	_ = decimal.New(0, 0)
}

func processPara() {
	// MOVE SPACES TO WS-LABEL
	WsLabel = strings.Repeat(" ", 20)
	// MOVE 0 TO WS-A-COUNT
	WsACount = 0
	// INSPECT LB-PART TALLYING WS-A-COUNT FOR ALL "A"
	// Count occurrences of "A" in LB-PART
	// COBOL INSPECT TALLYING FOR ALL counts non-overlapping occurrences
	// For single char, simple count
	WsACount = int64(strings.Count(partRec.LbPart, "A"))

	// STRING LB-REGION DELIMITED BY SPACE "-" DELIMITED BY SIZE LB-PART DELIMITED BY SPACE "-" DELIMITED BY SIZE LB-SERIAL DELIMITED BY SIZE INTO WS-LABEL
	partRegion := trimAtSpace(partRec.LbRegion)
	partPart := trimAtSpace(partRec.LbPart)
	serialFormatted := formatNumeric(partRec.LbSerial, 4)

	concatenated := partRegion + "-" + partPart + "-" + serialFormatted

	// INTO WS-LABEL : STRING does not clear target, but we already blanked.
	// Fill WS-LABEL with concatenated, left aligned, padded with spaces, truncated if overflow
	b := []byte(strings.Repeat(" ", 20))
	copy(b, []byte(concatenated))
	WsLabel = string(b)

	// INSPECT WS-LABEL REPLACING ALL "0" BY "O"
	WsLabel = strings.ReplaceAll(WsLabel, "0", "O")

	// ADD WS-A-COUNT TO WS-TOTAL-A
	WsTotalA += WsACount
	// ADD 1 TO WS-COUNT
	WsCount += 1

	// DISPLAY WS-LABEL " A=" WS-A-COUNT
	// WS-LABEL is X(20) prints as 20 chars, WS-A-COUNT is 99 zero padded to 2
	fmt.Fprintf(os.Stdout, "%s A=%s\n", WsLabel, formatNumeric(WsACount, 2))

	// PERFORM READ-PARA
	readPara()
}

func summaryPara() {
	fmt.Fprintf(os.Stdout, "LABELS: %s A-TOTAL: %s\n", formatNumeric(WsCount, 3), formatNumeric(WsTotalA, 3))
}

func main() {
	mainPara()
}
